<template>
  <section class="w-full h-full flex flex-col">
    <div class="flex justify-end">
      <NuxtLink :to="{ name: 'login' }">
        <Button variant="secondary" size="sm">Log In</Button>
      </NuxtLink>
    </div>
    <div class="p-6 flex flex-col flex-auto justify-center self-center gap-6 w-full max-w-[552px] max-lg:px-0">
      <h1 class="font-semibold text-2xl leading-6">Restore Password</h1>
      <form v-if="!submittedEmail" class="self-center flex flex-col gap-4 w-full justify-center" @submit="onSubmit">
        <p class="text-sm leading-5 text-muted-foreground">
          Enter your email address and we'll send you a link to reset your password.
        </p>
        <FormField
          v-slot="{ componentField }"
          name="email"
          :validate-on-model-update="false"
          :validate-on-blur="false"
          :validate-on-change="false"
        >
          <FormItem>
            <FormControl>
              <Label for="email">Email</Label>
              <Input
                id="email"
                type="text"
                placeholder="name@example.com"
                :disabled="isResettingPassword"
                v-bind="componentField"
              />
              <FormMessage />
            </FormControl>
          </FormItem>
        </FormField>
        <Button variant="default" class="w-full" size="lg" :loading="isResettingPassword" type="submit"
          >Send Reset Link</Button
        >
      </form>
      <template v-else>
        <Alert variant="success">
          <CheckIcon />
          <AlertTitle
            >A reset link was sent to <b class="wrap-anywhere">{{ submittedEmail }}</b></AlertTitle
          >
          <AlertDescription>Check your inbox and spam folder.</AlertDescription>
        </Alert>
        <NuxtLink :to="{ name: 'login' }" class="mx-auto">
          <Button variant="default" size="lg">Log In</Button>
        </NuxtLink>
      </template>
    </div>
  </section>
</template>

<script setup lang="ts">
import * as z from 'zod';
import { toTypedSchema } from '@vee-validate/zod';
import { useForm } from 'vee-validate';
import { CheckIcon } from 'lucide-vue-next';

useSeoMeta({
  title: 'Restore password',
  description:
    'Secure password recovery page enabling quick password reset and verification to seamlessly restore access to your account.',
});

definePageMeta({
  layout: 'login',
  auth: {
    unauthenticatedOnly: true,
    navigateAuthenticatedTo: '/projects',
  },
});

const submittedEmail = ref<string | null>(null);

const { resetPassword, isResettingPassword } = useResetPassword();

const formSchema = toTypedSchema(
  z.object({
    email: z
      .string({ message: 'Email is required' })
      .trim()
      .nonempty({ message: 'Email is required' })
      .email({ message: 'Email is invalid' }),
  })
);

const { handleSubmit } = useForm({
  validationSchema: formSchema,
});

const onSubmit = handleSubmit(async (values) => {
  console.log('values', values);
  resetPassword({ email: values.email })
    .then(() => {
      submittedEmail.value = values.email;
    })
    .catch((error) => {
      console.error('Error sending reset password email:', error);
    });
});

onUnmounted(() => (submittedEmail.value = null));
</script>

<style scoped lang="scss">
.wrap-anywhere {
  overflow-wrap: anywhere;
}
</style>
