import { accountPasswordReset } from '~/client';
import type { ResetPasswordRequest, ResetPasswordResponse } from '~/client';
import { showToastError, showToastSuccess } from '~/utils/show-toast';

export const useResetPassword = defineMutation(() => {
  const { mutateAsync: resetPasswordMutation, asyncStatus } = useMutation({
    mutation: (form: ResetPasswordRequest): Promise<ResetPasswordResponse> =>
      accountPasswordReset({
        composable: '$fetch',
        body: form,
      }),
    onSuccess: async () => {
      showToastSuccess('Reset password link was sent to your email');
    },
    onError(error) {
      showToastError(error);
    },
  });

  return {
    resetPassword: resetPasswordMutation,
    isResettingPassword: computed(() => asyncStatus.value === 'loading'),
  };
});
